'use strict';
// StudyTracker v4: plain JavaScript, no external packages, no telemetry.
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => Array.from(root.querySelectorAll(s));
const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pad = n => String(n).padStart(2, '0');
const fmt = seconds => {let n = Math.max(0, Number(seconds)||0); return n>=3600 ? `${(n/3600).toLocaleString(StudyI18n.locale(),{maximumFractionDigits:1})} h` : `${Math.round(n/60)} min`};
const dateKey = d => `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const isoDate = value => value ? dateKey(new Date(value)) : '';
const formatDate = value => value ? new Date(value).toLocaleDateString(StudyI18n.locale(),{day:'2-digit',month:'short',year:'numeric'}) : '–';
const COLORS = ['#7065EF','#1AA59A','#F4A35D','#488FDD','#CE6A98','#9A78D5'];
const svg = (paths) => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths}</svg>`;
