 $('#kanban').addEventListener('dragend',()=>{$$('.task-card.dragging').forEach(c=>c.classList.remove('dragging'));$$('.kanban-column').forEach(c=>c.classList.remove('drop-target'))});
 $('#kanban').addEventListener('dragover',e=>{const col=e.target.closest('[data-status]');if(col){e.preventDefault();e.dataTransfer.dropEffect='move';$$('.kanban-column').forEach(c=>c.classList.toggle('drop-target',c===col))}});
